import React from "react";
import { CommonTemplateTypes } from "../common-template-types";
import {
  Layout,
  StoryElement,
  Spacer,
  LiveList,
  IncompatibleBanner,
  Footer,
  GoogleTagManager,
  GoogleAnalytics,
  QuintypeAnalytics,
  ComScore,
  ChartBeat,
  InfiniteScroll,
  Fonts
} from "../../atoms";
import { HeaderCard, Navbar, RelatedStories, WebEngage } from "../../molecules";
import { TopAd, BodyAd, BottomAd } from "../../molecules/ads";
import { StoryContainer, Wrapper } from "./presentational-components";
import { CardUpdatedAt } from "./container-components";
import get from "lodash.get";
import { StoryPageSlots } from "../../molecules/slots";
import { BODY_AD_MAX_LIMIT, BODY_WIDGET_MAX_LIMIT } from "../../constants";
import { AdWrapper } from "../../molecules/ads/shared/components";
import { decodeB64, isBase64 } from "../../utils/utils";

const { TopSlot, BottomSlot, LiveBlogCardSlot } = StoryPageSlots;

/**
 * The LiveBlog is the default template for live blog type stories.
 *
 * Slots: top-slot, bottom-slot, live-blog-card-slot
 *
 * renders: In addition to all renders offered by the generic story template, live blog offers the following renders:
 *  - liveBlogCardTimeStamp
 *
 * featureConfig: In addition to all feature configs provided by generic story template, live blog accepts following feature configs. They can be accessed via opts.featureConfig.liveBlog
 *  - dataPollInterval: sets the data-poll-interval attr on <amp-live-list />
 *  - dataMaxItemsPerPage: sets the data-max-items-per-page attr on <amp-live-list />
 *
 * @category Default Templates
 * @component
 */
export const LiveBlog = ({ story, config }: CommonTemplateTypes) => {
  const footerText = get(config, ["publisherConfig", "publisher-settings", "copyright"], null);
  // checking for body-ads key
  const bodyAdsConfig = get(config, ["ampConfig", "doubleclick", "body-ads"], null);
  const hasMultipleBodyAds = Array.isArray(bodyAdsConfig) && bodyAdsConfig.length > 0;
  const bodyAdsToRender = (bodyAdsConfig || []).slice(0, BODY_AD_MAX_LIMIT);

  const customAmpWidgets = get(config, ["opts", "customAmpWidgets"]);
  const widgets =
    get(config, ["additionalConfig", "story", "ampWidgets"]) ||
    (typeof customAmpWidgets === "function" ? customAmpWidgets() : customAmpWidgets);

  const widgetArray = Array.isArray(widgets) ? widgets : [];

  const bodyWidgetsToRender = widgetArray.slice(0, BODY_AD_MAX_LIMIT);
  const enabledWidgets = widgetArray.filter((w) => w?.enable && w?.code);

  const infiniteScrollInlineConfig = get(
    config,
    ["opts", "featureConfig", "infiniteScroll", "infiniteScrollInlineConfig"],
    null
  );

  const infiniteScrollExists = !!(infiniteScrollInlineConfig && infiniteScrollInlineConfig.length);
  let lastComponent = <Footer text={footerText} />;
  let navbarComponent = <Navbar />;
  if (infiniteScrollExists) {
    lastComponent = (
      <InfiniteScroll inlineConfig={infiniteScrollInlineConfig}>
        <div next-page-hide="true" footer="true">
          <Footer text={footerText} />
        </div>
      </InfiniteScroll>
    );
    navbarComponent = (
      <div next-page-hide="true">
        <Navbar />
      </div>
    );
  }
  const templateName = "liveBlog";
  return (
    <Layout story={story} config={config}>
      {navbarComponent}
      <Fonts />
      <IncompatibleBanner />
      <GoogleTagManager />
      <Wrapper>
        <TopAd templateName={templateName} />
        <TopSlot />
        <Spacer token="s" />
        <StoryContainer>
          <HeaderCard storyType="live-blog" config={config} />
          <WebEngage />
          <Spacer token="m" />
          <LiveList>
            {story.cards.map((card, idx) => {
              const customCardRender = get(config, ["opts", "render", "storyCardRenderProps"], {});
              const cardtype = get(card, ["metadata", "attributes", "cardtype", "0"], "");
              if (customCardRender[cardtype] && typeof customCardRender[cardtype] === "function") {
                return (
                  <div
                    key={card.id}
                    id={card.id}
                    data-test-id="styled-live-blog-cards"
                    data-sort-time={card["card-added-at"]}
                    data-update-time={card["card-updated-at"]}>
                    {customCardRender[cardtype]({ story, config, card })}
                    <CardUpdatedAt timeStamp={card["card-added-at"]} card={card} />
                  </div>
                );
              }
              const storyCard = card["story-elements"].map((element) => (
                <StoryElement key={element.id} element={element} noSpacer={true} />
              ));
              const adSlot = hasMultipleBodyAds ? bodyAdsToRender[idx] : undefined;

              const slot = bodyWidgetsToRender[idx];

              const widgetSlot =
                idx < BODY_WIDGET_MAX_LIMIT && slot?.enable
                  ? isBase64(slot.code)
                    ? decodeB64(slot.code)
                    : slot.code
                  : null;

              return (
                <div
                  key={card.id}
                  id={card.id}
                  data-sort-time={card["card-added-at"]}
                  data-test-id="styled-live-blog-cards"
                  data-update-time={card["card-updated-at"]}>
                  {storyCard}
                  <CardUpdatedAt timeStamp={card["card-updated-at"]} card={card} />
                  {enabledWidgets.length > 0 ? (
                    <>
                      {idx === 0 && <BodyAd templateName={templateName} />}
                      {widgetSlot && (
                        <AdWrapper>
                          <div dangerouslySetInnerHTML={{ __html: widgetSlot }} />
                          <Spacer token="s" />
                        </AdWrapper>
                      )}
                    </>
                  ) : hasMultipleBodyAds ? (
                    adSlot && <BodyAd adSlot={adSlot} templateName={templateName} />
                  ) : (
                    idx === 0 && <BodyAd templateName={templateName} />
                  )}
                  <LiveBlogCardSlot index={idx} card={card} />
                </div>
              );
            })}
          </LiveList>
          <RelatedStories />
        </StoryContainer>
        <BottomSlot />
        <BottomAd templateName={templateName} />
      </Wrapper>
      <GoogleAnalytics />
      <QuintypeAnalytics />
      <ComScore />
      <ChartBeat />
      {lastComponent}
    </Layout>
  );
};
